final class TableClothRenderingTest {
    private static final BlockPos T=new BlockPos(2244,4,5),B=T.east(),S=new BlockPos(2240,4,3),C=new BlockPos(2247,5,8);
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var network=UUID.randomUUID();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 2244 8 12");context.waitFor(client->Math.abs(client.player.getX()-2244.5)<.1,300);
        var ready=new AtomicBoolean();for(int i=0;i<300&&!ready.get();i++){server.runOnServer(ignored->ready.set(world.getConnection().getServerLevel().isLoaded(S)&&world.getConnection().getServerLevel().isLoaded(C)));if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError("Shop scene chunks unavailable");
        server.runCommand("fill 2234 3 0 2255 3 15 minecraft:smooth_quartz");server.runCommand("setblock 2247 4 8 minecraft:smooth_quartz");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var player=level.getServer().getPlayerList().getPlayers().getFirst();level.setBlockAndUpdate(S.north(),Blocks.BARREL.defaultBlockState());((BarrelBlockEntity)level.getBlockEntity(S.north())).setItem(0,new ItemStack(Items.APPLE,32));level.setBlockAndUpdate(S,AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));level.setBlockAndUpdate(S.above(),AllBlocks.STOCK_LINK.defaultBlockState());var link=(PackagerLinkBlockEntity)level.getBlockEntity(S.above());link.behaviour.setFrequency(network);link.initialize();level.setBlockAndUpdate(T,AllBlocks.STOCK_TICKER.defaultBlockState());var ticker=(StockTickerBlockEntity)level.getBlockEntity(T);ticker.behaviour.setFrequency(network);ticker.tick();level.setBlockAndUpdate(B,AllBlocks.BLAZE_BURNER.defaultBlockState().setValue(BlazeBurnerBlock.HEAT_LEVEL,BlazeBurnerBlock.HeatLevel.SMOULDERING));player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllBlocks.TABLE_CLOTHS.get(DyeColor.RED),2));});
        context.runOnClient(client->{for(var block:AllBlocks.tableCloths())for(var state:block.getStateDefinition().getPossibleStates()){var model=client.getModelManager().getBlockStateModelSet().get(state);if(model==client.getModelManager().getBlockStateModelSet().missingModel())throw new AssertionError("Missing cloth model: "+state);}});
        server.runCommand("gamemode survival @p");server.runCommand("tp @p 2245.5 4 9.5");
        context.waitFor(client->!client.player.isSpectator()&&client.player.getMainHandItem().getItem() instanceof TableClothBlockItem&&Math.abs(client.player.getX()-2245.5)<.1,200);
        lookBlock(context,B);context.waitTicks(2);context.getInput().pressKey(options->options.keyUse);
        try{context.waitFor(client->client.gui.screen() instanceof StockTickerScreen,200);}catch(AssertionError failure){
            context.runOnClient(client->Create.LOGGER.error("Shop fixture open state: screen={}, hit={}, held={}, position={}",client.gui.screen(),client.hitResult,client.player.getMainHandItem(),client.player.position()));
            server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var player=level.getServer().getPlayerList().getPlayers().getFirst();var ticker=(StockTickerBlockEntity)level.getBlockEntity(T);Create.LOGGER.error("Shop fixture server: menu={}, keeper={}, allowed={}, stock={}",player.containerMenu,ticker.isKeeperPresent(),ticker.behaviour.mayInteract(player),ticker.getAccurateSummary().getStacksByCount());});throw failure;
        }
        context.waitFor(client->((StockTickerScreen)client.gui.screen()).getMenu().stock.size()==1,200);
        context.runOnClient(client->{var screen=(StockTickerScreen)client.gui.screen();screen.searchBox().setValue("apple");var point=screen.stockPosition(0,0);mouse(screen,point);screen.mouseScrolled(point.x,point.y,0,3);screen.addressBox().setValue("Market");screen.sendOrder();});
        context.waitFor(client->client.gui.screen()==null&&client.player.getMainHandItem().has(AllDataComponents.AUTO_REQUEST_DATA),200);
        context.runOnClient(client->{var data=client.player.getMainHandItem().get(AllDataComponents.AUTO_REQUEST_DATA);if(data.encodedRequest().stacks().getFirst().count!=4||!data.targetOffset().equals(T))throw new AssertionError("Shop programming lost order or absolute keeper location");});
        server.runCommand("tp @p 2247.5 4 11.5");context.waitFor(client->Math.abs(client.player.getX()-2247.5)<.1,200);look(context,Vec3.atLowerCornerOf(C).add(.5,-.001,.5));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(C.below())&&hit.getDirection()==Direction.UP,200);context.waitTicks(5);context.getInput().pressKey(options->options.keyUse);context.waitTicks(5);
        context.takeScreenshot("create-vulkan-table-cloth-placed");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var be=level.getBlockEntity(C);var held=level.getServer().getPlayerList().getPlayers().getFirst().getMainHandItem();if(!(be instanceof TableClothBlockEntity cloth)||!cloth.isShop())throw new AssertionError("Actual placement did not configure shop: state="+level.getBlockState(C)+", below="+level.getBlockState(C.below())+", entity="+be+", held="+held+", data="+held.get(AllDataComponents.AUTO_REQUEST_DATA));});
        context.waitFor(client->client.level.getBlockEntity(C) instanceof TableClothBlockEntity cloth&&cloth.isShop(),200);context.waitFor(client->client.player.getMainHandItem().getCount()==1,200);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var player=level.getServer().getPlayerList().getPlayers().getFirst();var cloth=(TableClothBlockEntity)level.getBlockEntity(C);if(!player.getUUID().equals(cloth.owner)||cloth.getTicker()!=level.getBlockEntity(T)||!cloth.getPaymentItem().isEmpty())throw new AssertionError("Placed shop owner/link/price invalid");player.getInventory().setItem(10,player.getMainHandItem().copy());player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIAMOND,8));});
        context.waitFor(client->client.player.getMainHandItem().is(Items.DIAMOND),200);lookPrice(context);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->((TableClothBlockEntity)client.level.getBlockEntity(C)).getPaymentItem().is(Items.DIAMOND),200);
        context.getInput().holdKey(options->options.keyUse);context.waitFor(client->client.gui.screen() instanceof FilterAmountScreen,200);
        var coordinate=context.computeOnClient(client->{var point=((FilterAmountScreen)client.gui.screen()).getCoordinateOfValue(1,2);float scaleX=(float)client.getWindow().getScreenWidth()/client.getWindow().getGuiScaledWidth();float scaleY=(float)client.getWindow().getScreenHeight()/client.getWindow().getGuiScaledHeight();return new Vec2(point.x*scaleX,point.y*scaleY);});context.getInput().setCursorPos(coordinate.x,coordinate.y);context.waitTicks(3);context.takeScreenshot("create-vulkan-table-cloth-price-board");context.getInput().releaseKey(options->options.keyUse);
        context.waitFor(client->client.gui.screen()==null&&((TableClothBlockEntity)client.level.getBlockEntity(C)).getPaymentAmount()==2,200);
        server.runOnServer(ignored->{var player=world.getConnection().getServerLevel().getServer().getPlayerList().getPlayers().getFirst();if(player.getMainHandItem().getCount()!=8)throw new AssertionError("Price ghost consumed currency");player.getInventory().setItem(9,player.getMainHandItem().copy());player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);});context.waitFor(client->client.player.getMainHandItem().isEmpty(),200);
        look(context,Vec3.atLowerCornerOf(C).add(.25,1/16.,.25));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(C)&&!((TableClothBlockEntity)client.level.getBlockEntity(C)).targetsPriceTag(hit),200);
        context.getInput().pressKey(options->options.keyUse);context.waitFor(client->ShoppingListItem.getList(client.player.getMainHandItem())!=null,200);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->ShoppingListItem.getList(client.player.getMainHandItem()).getPurchases(C)==2,200);
        context.waitFor(client->((TableClothBlockEntity)client.level.getBlockEntity(C)).clientStock.getCountOf(new ItemStack(Items.APPLE))==32,200);context.takeScreenshot("create-vulkan-table-cloth-selected-purchases");
        context.runOnClient(client->{var extracted=client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(C),.5f,null,false);if(!(extracted instanceof TableClothRenderer.State state)||!state.shop||state.items.size()!=1||state.tag.mesh==null||state.tag.mesh.size()==0||state.price.isEmpty())throw new AssertionError("Native shop display/price render state missing");});
        server.runCommand("tp @p 2245.5 4 9.5");context.waitFor(client->Math.abs(client.player.getX()-2245.5)<.1,200);lookBlock(context,B);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->client.player.getMainHandItem().isEmpty(),200);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var ticker=(StockTickerBlockEntity)level.getBlockEntity(T);var player=level.getServer().getPlayerList().getPlayers().getFirst();if(ticker.receivedPayments.inputs.stream().mapToLong(slot->slot.getAmount()).sum()!=4||player.getInventory().getItem(9).getCount()!=4||((BarrelBlockEntity)level.getBlockEntity(S.north())).getItem(0).getCount()!=24)throw new AssertionError("Real shopping payment/stock totals differ");var box=((PackagerBlockEntity)level.getBlockEntity(S)).heldBox;if(!PackageItem.getAddress(box).equals("Market")||PackageItem.getContents(box).stream().mapToInt(ItemStack::getCount).sum()!=8)throw new AssertionError("Shopping did not produce exact addressed parcel");});
        server.runCommand("gamemode spectator @p");server.runCommand("tp @p 2248 8 12");context.waitFor(client->client.player.isSpectator(),200);look(context,Vec3.atCenterOf(C));world.getConnection().waitForChunksRender();context.takeScreenshot("create-vulkan-table-cloth-shop");
        int isolated=context.computeOnClient(client->quads(client,C));var key=context.computeOnClient(client->geometryKey(client,C));
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();level.setBlockAndUpdate(C.south(),AllBlocks.TABLE_CLOTHS.get(DyeColor.GREEN).defaultBlockState());for(int i=0;i<AllBlocks.tableCloths().length;i++)level.setBlockAndUpdate(new BlockPos(2236+i%10,4,13+i/10),AllBlocks.tableCloths()[i].defaultBlockState());var display=new BlockPos(2240,4,11);level.setBlockAndUpdate(display,AllBlocks.ANDESITE_TABLE_CLOTH.defaultBlockState().setValue(TableClothBlock.HAS_BE,true));var cloth=(TableClothBlockEntity)level.getBlockEntity(display);cloth.manuallyAddedItems.addAll(List.of(new ItemStack(Items.APPLE),new ItemStack(Items.STONE),new ItemStack(AllItems.ANDESITE_ALLOY),new ItemStack(Items.DIAMOND)));cloth.notifyUpdate();});
        context.waitFor(client->client.level.getBlockState(C.south()).getBlock() instanceof TableClothBlock&&((TableClothBlockEntity)client.level.getBlockEntity(C)).sideOccluded,200);
        context.runOnClient(client->{if(quads(client,C)!=isolated-8||Objects.equals(key,geometryKey(client,C)))throw new AssertionError("Joining a cloth must remove exactly its two bordering corner pieces and change the geometry cache key");var state=(TableClothRenderer.State)client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(C),.5f,null,false);if(!state.topPrice||state.pricePosition.y<=0)throw new AssertionError("Occluded hanging price did not move onto top");});
        look(context,new Vec3(2243,4.5,12));world.getConnection().waitForChunksRender();context.takeScreenshot("create-vulkan-table-cloth-colors-and-connected-corners");
        var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);context.runOnClient(client->{var extracted=(TableClothRenderer.State)client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(C),.5f,null,false);if(extracted.tag.mesh==null||extracted.tag.mesh.size()==0)throw new AssertionError("Shop mesh missing after reload");});
        server.runCommand("tp @p 5000 10 5000");var unloaded=new AtomicBoolean();for(int i=0;i<120&&!unloaded.get();i++){context.waitTicks(5);server.runOnServer(ignored->unloaded.set(!world.getConnection().getServerLevel().isLoaded(C)));}if(!unloaded.get())throw new AssertionError("Shop retained scene chunk");server.runCommand("tp @p 2248 8 12");context.waitFor(client->Math.abs(client.player.getX()-2248.5)<.1&&client.level.getBlockEntity(C) instanceof TableClothBlockEntity cloth&&cloth.getPaymentAmount()==2&&cloth.isShop(),400);
        var returned=new AtomicBoolean();for(int i=0;i<300&&!returned.get();i++){server.runOnServer(ignored->returned.set(LoadedLevelAccess.blockEntity(world.getConnection().getServerLevel(),C) instanceof TableClothBlockEntity));if(!returned.get())context.waitTicks(1);}if(!returned.get())throw new AssertionError("Shop chunk has not returned to FULL");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var cloth=(TableClothBlockEntity)LoadedLevelAccess.blockEntity(level,C);if(cloth.getTicker()==null||!cloth.getPaymentItem().is(Items.DIAMOND)||!cloth.requestData.encodedTargetAddress().equals("Market"))throw new AssertionError("Shop save/return lost data");});context.takeScreenshot("create-vulkan-table-cloth-after-chunk-return");
    }
    private static void lookPrice(ClientGameTestContext context){var at=context.computeOnClient(client->{var cloth=(TableClothBlockEntity)client.level.getBlockEntity(C);return Vec3.atLowerCornerOf(C).add(cloth.pricePosition());});look(context,at);context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(C)&&((TableClothBlockEntity)client.level.getBlockEntity(C)).targetsPriceTag(hit),200);}
    private static Object geometryKey(net.minecraft.client.Minecraft client,BlockPos pos){var state=client.level.getBlockState(pos);return client.getModelManager().getBlockStateModelSet().get(state).createGeometryKey((net.minecraft.client.renderer.block.BlockAndTintGetter)client.level,pos,state,net.minecraft.util.RandomSource.create(42));}
    private static int quads(net.minecraft.client.Minecraft client,BlockPos pos){var state=client.level.getBlockState(pos);var model=client.getModelManager().getBlockStateModelSet().get(state);if(!(model instanceof TableClothModel))throw new AssertionError("Missing cloth wrapper");var mesh=Renderer.get().mutableMesh();model.emitQuads(mesh.emitter(),(net.minecraft.client.renderer.block.BlockAndTintGetter)client.level,pos,state,net.minecraft.util.RandomSource.create(42),side->false);return mesh.immutableCopy().size();}
    private static void mouse(StockTickerScreen screen,Vec2 point){var event=new net.minecraft.client.input.MouseButtonEvent(point.x,point.y,new net.minecraft.client.input.MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,0));screen.mouseClicked(event,false);screen.mouseReleased(event);}
    private static void lookBlock(ClientGameTestContext context,BlockPos pos){look(context,Vec3.atCenterOf(pos));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(pos),200);}
    private static void look(ClientGameTestContext context,Vec3 point){var rotation=context.computeOnClient(client->{var delta=point.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});context.getInput().lookAt(rotation.x,rotation.y);}
}
